// Types of contracts/identity-api-v1.yaml (and the shared contracts/common-problem-v1.yaml components).
// ADR-0001 has these generated by openapi-typescript; the generator is not yet a dependency, so this file is
// written by hand to the same names and shapes. Keep it in step with the contract.

export type ProblemCode =
  | 'VALIDATION_FAILED'
  | 'MALFORMED_REQUEST'
  | 'IDENTIFIER_TAKEN'
  | 'INVALID_CREDENTIALS'
  | 'UNAUTHENTICATED'
  | 'CLIENT_HEADER_MISSING'
  | 'NOT_FOUND'
  | 'METHOD_NOT_ALLOWED'
  | 'UNSUPPORTED_MEDIA_TYPE'
  | 'REQUEST_REJECTED'
  | 'INTERNAL_ERROR';

export type FieldErrorCode =
  | 'REQUIRED'
  | 'BLANK'
  | 'TOO_SHORT'
  | 'TOO_LONG'
  | 'INVALID_FORMAT'
  | 'INVALID_TYPE'
  | 'INVALID_DATE'
  | 'INVALID_VALUE'
  | 'UNKNOWN_FIELD'
  | 'TAKEN';

export interface Problem {
  type: string;
  title: string;
  status: number;
  detail?: string;
  code: ProblemCode;
  errors: { field: string; code: FieldErrorCode; message: string }[];
}

export interface User {
  identifier: string;
}

export interface Session {
  user: User;
  expiresAt: string;
}

export interface SignupRequest {
  identifier: string;
  password: string;
}

export interface SignupResult {
  user: User;
}

export interface LoginRequest {
  identifier: string;
  password: string;
}
